        render(
            <Wrapper>
                <TableScore
                    table={TableNameSchema.enum.pub}
                    playerRecord={defaultPlayerRecord}
                />
            </Wrapper>,
        );

        expect(
            screen.getByText(String(defaultPlayerRecord.scorePub)),
        ).toBeInTheDocument();
    });

