            <Wrapper>
                <TableScore
                    table={TableNameSchema.enum.pub}
                    playerRecord={minimalPlayerRecord}
                />
            </Wrapper>,
        );

        expect(screen.getByText('-')).toBeInTheDocument();
    });
});
